CREATE OR REPLACE FUNCTION public.thread_record_phase10_evidence(p_actor jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ev jsonb; graph_ev jsonb; seq bigint; BEGIN PERFORM public._assert_actor(p_actor); IF p_actor->>'kind'<>'human' OR NOT public.has_role((p_actor->>'id')::uuid,'steward') THEN RAISE EXCEPTION 'STEWARD_REQUIRED'; END IF; ev:=public.thread_phase10_selftest(); graph_ev:=public.thread_phase10_graph_test(); ev:=ev||jsonb_build_object('passed',(ev->>'passed')::boolean AND (graph_ev->>'passed')::boolean,'checks',ev->'checks'||(graph_ev->'checks'),'fixture_mode','explicit observations and native connected graph; rollback-only; live external evidence pending'); seq:=public._mcp_ledger(p_actor,'phase10.exit_evidence',NULL,ev); RETURN ev||jsonb_build_object('ledger_seq',seq); END $$;
DO $$ DECLARE source text; BEGIN SELECT pg_get_functiondef('public.thread_framing_sweep(jsonb)'::regprocedure) INTO source; source:=replace(source,'where f.state = ''open'' and f.detector_key = any(keys)','where f.state = ''open'' and f.evidence->>''phase10'' IS DISTINCT FROM ''true'' and f.detector_key = any(keys)'); EXECUTE source; END $$;
DO $$ DECLARE ev jsonb; graph_ev jsonb; BEGIN ev:=public.thread_phase10_selftest(); graph_ev:=public.thread_phase10_graph_test(); IF ev->>'passed'<>'true' OR graph_ev->>'passed'<>'true' THEN RAISE EXCEPTION 'Phase10 acceptance failed: % %',ev,graph_ev; END IF; PERFORM public._mcp_ledger('{"kind":"system","id":"phase10-automated","authority_used":"observe"}','phase10.automated_evidence',NULL,jsonb_build_object('passed',true,'checks',ev->'checks'||(graph_ev->'checks'),'fixture_mode','rollback-only; explicit observations and native graph chain; UI verification pending sign-in')); END $$;